        excel =_phase2_excel_bytes ({"Backtest":bt_baseline if bt_baseline is not None else _backtest_frame (cfg ,data )},summary )
        pdf =_phase2_pdf_bytes (f"Nobody Dealer Suite — Phase 2 Report ({cfg ['asset']})",summary )
