# --------------------------------------------------------------------------
# GLOBAL SPOT VENUES — เพิ่มกระดาน Spot ขนาดใหญ่เข้า Board เดียวกัน
# หมายเหตุ: Global Venue Board ใช้ Spot เท่านั้น; ไม่มี funding/perpetual execution ในตารางนี้
# เพื่อไม่ให้เอาคนละ market type มาเทียบกันผิดความหมาย
# --------------------------------------------------------------------------
def _spot_kraken(b: str) -> tuple[float, float, float]:
    pair = "XBTUSD" if b.upper() == "BTC" else f"{b.upper()}USD"
    d = _http_json(f"https://api.kraken.com/0/public/Ticker?pair={pair}")
    result = d.get("result") or {}
    if not result:
        raise ValueError("empty Kraken ticker")
    x = next(iter(result.values()))
    last = float(x["c"][0])
    open_px = float(x["o"])
    vol24 = float(x["v"][1])
    chg = ((last / open_px) - 1.0) * 100.0 if open_px > 0 else 0.0
    return last, chg, last * vol24


def _spot_coinbase(b: str) -> tuple[float, Optional[float], float]:
    pair = f"{b.upper()}-USD"
    d = _http_json(f"https://api.exchange.coinbase.com/products/{pair}/ticker")
    last = float(d["price"])
    volume = float(d.get("volume") or 0.0)
    # ticker ไม่มี % เปลี่ยนแปลง → คำนวณจาก open 24h ใน /stats
    # ถ้าดึง stats ไม่ได้ให้คืน None (UI แสดง "—") แทนการเดาเป็น 0%
    chg: Optional[float] = None
    try:
        s = _http_json(f"https://api.exchange.coinbase.com/products/{pair}/stats", timeout=4.0)
        open_px = float(s.get("open") or 0.0)
        if open_px > 0:
            chg = (last / open_px - 1.0) * 100.0
    except Exception:
        chg = None
    return last, chg, last * volume


def _spot_bitstamp(b: str) -> tuple[float, float, float]:
    pair = f"{b.lower()}usd"
    d = _http_json(f"https://www.bitstamp.net/api/v2/ticker/{pair}/")
    last = float(d["last"])
    chg = float(d.get("percent_change_24") or 0.0)
    volume = float(d.get("volume") or 0.0)
    return last, chg, last * volume


def _spot_bitfinex(b: str) -> tuple[float, float, float]:
    symbol = f"t{b.upper()}USD"
    d = _http_json(f"https://api-pub.bitfinex.com/v2/ticker/{symbol}")
    last = float(d[6])
    chg = float(d[5]) * 100.0
    volume = float(d[7])
    return last, chg, last * volume


def _spot_kucoin(b: str) -> tuple[float, float, float]:
    symbol = f"{b.upper()}-USDT"
    # Level-1 endpoint supplied for the board's live price.
    level1 = _http_json(
        f"https://api.kucoin.com/api/v1/market/orderbook/level1?symbol={symbol}"
    )
    data = level1.get("data") or {}
    last = float(data["price"])

    # KuCoin's 24h stats endpoint supplies quote turnover and 24h change.
    stats = _http_json(
        f"https://api.kucoin.com/api/v1/market/stats?symbol={symbol}"
    )
    sd = stats.get("data") or {}
    chg = float(sd.get("changeRate") or 0.0) * 100.0
    turnover = float(sd.get("volValue") or 0.0)
    return last, chg, turnover


# --------------------------------------------------------------------------
# GLOBAL SPOT VENUES — former perpetual venues are now represented by SPOT
# --------------------------------------------------------------------------
def _spot_binance(b: str) -> tuple[float, float, float]:
    """Binance Spot 24h ticker with multiple official public API fallbacks.

    Some hosted regions can fail against api.binance.com even though Binance
    documents several equivalent public endpoints. data-api.binance.vision
    explicitly exposes /api/v3/ticker/24hr, while api1-api4 are alternate
    Binance API hosts.
    """
    symbol = f"{b.upper()}USDT"
    urls = [
        f"https://data-api.binance.vision/api/v3/ticker/24hr?symbol={symbol}",
        f"https://api.binance.com/api/v3/ticker/24hr?symbol={symbol}",
        f"https://api1.binance.com/api/v3/ticker/24hr?symbol={symbol}",
        f"https://api2.binance.com/api/v3/ticker/24hr?symbol={symbol}",
        f"https://api3.binance.com/api/v3/ticker/24hr?symbol={symbol}",
        f"https://api4.binance.com/api/v3/ticker/24hr?symbol={symbol}",
        f"https://api-gcp.binance.com/api/v3/ticker/24hr?symbol={symbol}",
    ]
    last_err = None
    for url in urls:
        try:
            d = _http_json(url, timeout=5.0)
            return (
                float(d["lastPrice"]),
                float(d["priceChangePercent"]),
                float(d["quoteVolume"]),
            )
        except Exception as e:
            last_err = e
    raise RuntimeError(f"Binance Spot unavailable: {type(last_err).__name__ if last_err else 'unknown'}")


def _spot_gate(b: str) -> tuple[float, float, float]:
    d = _http_json(f"https://api.gateio.ws/api/v4/spot/tickers?currency_pair={b.upper()}_USDT")[0]
    return float(d["last"]), float(d.get("change_percentage") or 0.0), float(d.get("quote_volume") or 0.0)


def _spot_hyperliquid(b: str) -> tuple[float, float, float]:
    """Read the real Hyperliquid Spot BTC market without accepting bad quotes.

    Hyperliquid's Spot metadata can contain wrapped/non-canonical token names.
    For BTC we therefore resolve the pair by token indices, prefer the
    canonical UBTC/BTC -> USDC market, and reject implausible BTC prices.
    If the summary context is missing/zero/suspicious, use the actual Spot L2
    book for that exact universe entry.  A bad/zero quote must never reach the
    Global Spot VWAP/arb calculations.
    """
    target = str(b).upper().strip()
    doc = _http_json(
        "https://api.hyperliquid.xyz/info",
        {"type": "spotMetaAndAssetCtxs"},
        timeout=8.0,
    )
    if not isinstance(doc, (list, tuple)) or len(doc) < 2:
        raise ValueError("Hyperliquid invalid spotMetaAndAssetCtxs payload")

    meta, ctxs = doc[0], doc[1]
    tokens = meta.get("tokens") if isinstance(meta, dict) else []
    universe = meta.get("universe") if isinstance(meta, dict) else []
    if not isinstance(tokens, list) or not isinstance(universe, list):
        raise ValueError("Hyperliquid invalid Spot metadata")

    token_names = {}
    for t in tokens:
        if not isinstance(t, dict):
            continue
        try:
            token_names[int(t.get("index"))] = str(t.get("name") or "").upper()
        except (TypeError, ValueError):
            continue

    # Resolve the actual BTC/USDC universe entry.  Prefer canonical pairs and
    # never accept an arbitrary literal "BTC/USDC" if its token indices point
    # to a different asset.
    candidates = []
    for i, u in enumerate(universe):
        if not isinstance(u, dict):
            continue
        pair_tokens = u.get("tokens") or []
        if len(pair_tokens) < 2:
            continue
        try:
            base_name = token_names.get(int(pair_tokens[0]), "")
            quote_name = token_names.get(int(pair_tokens[1]), "")
        except (TypeError, ValueError):
            continue
        if quote_name not in {"USDC", "USDT"}:
            continue

        uname = str(u.get("name") or "").upper().strip()
        parts = [x.strip() for x in uname.split("/") if x.strip()]
        literal = len(parts) >= 2 and parts[0] in {target, "UBTC"} and parts[1] == "USDC"
        btc_alias = target == "BTC" and base_name in {"BTC", "UBTC"} and quote_name == "USDC"
        token_match = base_name == target and quote_name == "USDC"
        if not (literal or btc_alias or token_match):
            continue

        canonical = bool(u.get("isCanonical"))
        # Canonical BTC/USDC/UBTC is strongly preferred; the other terms are
        # only fallbacks when Hyperliquid changes its metadata naming.
        score = (
            100 if canonical else 0
        ) + (
            20 if base_name == "UBTC" else 10 if base_name == "BTC" else 0
        ) + (
            10 if uname in {"UBTC/USDC", "BTC/USDC"} else 0
        )
        candidates.append((score, i, u, base_name, quote_name))

    if not candidates:
        raise ValueError("Hyperliquid BTC Spot pair not found")

    _, match_i, match_u, base_name, quote_name = max(candidates, key=lambda x: x[0])
    ctx = ctxs[match_i] if isinstance(ctxs, list) and match_i < len(ctxs) and isinstance(ctxs[match_i], dict) else {}

    def _num(v):
        try:
            return float(v)
        except (TypeError, ValueError):
            return 0.0

    prev = _num(ctx.get("prevDayPx"))
    turn = _num(ctx.get("dayNtlVlm"))

    # For BTC, anything far below normal BTC scale is invalid.  This guard is
    # deliberately conservative: it prevents a wrapped-token/metadata mismatch
    # from becoming a fake $0.0 quote and a false arbitrage winner.
    def _valid_btc_price(v):
        return v > 1000.0 if target == "BTC" else v > 0.0

    px = 0.0
    for key in ("midPx", "markPx", "oraclePx"):
        candidate_px = _num(ctx.get(key))
        if _valid_btc_price(candidate_px):
            px = candidate_px
            break

    # Always have the exact universe name available for L2.  If the summary
    # context is zero or suspicious, use the real Spot order book instead.
    if not _valid_btc_price(px):
        # Hyperliquid uses the generic `l2Book` info method for Spot too.
        # For Spot pairs, the coin identifier is the universe index (e.g. @107),
        # not the display name such as UBTC/USDC. Using `spotL2Book` causes HTTP 422.
        spot_index = match_u.get("index")
        try:
            coin = "@" + str(int(spot_index))
        except (TypeError, ValueError):
            coin = str(match_u.get("name") or "").strip()
        if not coin:
            raise ValueError("Hyperliquid Spot pair has no valid universe index")
        book = _http_json(
            "https://api.hyperliquid.xyz/info",
            {"type": "l2Book", "coin": coin},
            timeout=8.0,
        )
        levels = book.get("levels") if isinstance(book, dict) else None
        bids = levels[0] if isinstance(levels, list) and len(levels) >= 1 else []
        asks = levels[1] if isinstance(levels, list) and len(levels) >= 2 else []

        bid = 0.0
        ask = 0.0
        for x in bids or []:
            if not isinstance(x, dict):
                continue
            q = _num(x.get("px"))
            if _valid_btc_price(q):
                bid = max(bid, q)
        for x in asks or []:
            if not isinstance(x, dict):
                continue
            q = _num(x.get("px"))
            if _valid_btc_price(q):
                ask = q if ask <= 0 else min(ask, q)

        if bid > 0 and ask > 0:
            px = (bid + ask) / 2.0
        elif bid > 0:
            px = bid
        elif ask > 0:
            px = ask

    if not _valid_btc_price(px):
        raise ValueError("Hyperliquid BTC Spot price invalid/unavailable")

    chg = ((px / prev) - 1.0) * 100.0 if prev > 0 else 0.0
    return px, chg, turn

def _spot_bitget_global(b: str) -> tuple[float, float, float]:
    d = _http_json(f"https://api.bitget.com/api/v3/market/tickers?category=SPOT&symbol={b.upper()}USDT")
    x = (d.get("data") or [])[0]
    return float(x["lastPrice"]), float(x.get("price24hPcnt") or 0.0) * 100.0, float(x.get("turnover24h") or 0.0)


def _spot_okx_global(b: str) -> tuple[float, float, float]:
    d = _http_json(f"https://www.okx.com/api/v5/market/ticker?instId={b.upper()}-USDT")["data"][0]
    last, op = float(d["last"]), float(d["open24h"])
    chg = ((last / op) - 1.0) * 100.0 if op > 0 else 0.0
    # For SPOT, OKX volCcy24h is quote-currency volume.
    return last, chg, float(d.get("volCcy24h") or 0.0)


def _spot_bitunix_global(b: str) -> tuple:
    """Read Bitunix Spot price with direct REST first and a real-market fallback.

    Bitunix documents the public Spot REST endpoints, but some hosted IPs can
    receive HTTP 403 from api.bitunix.com. In that case, use CoinGecko's
    Bitunix exchange ticker as a secondary market-data source. CoinGecko
    exposes exchange-specific tickers and keeps the exchange identity attached
    to the ticker, so this is still Bitunix Spot data rather than a generic BTC
    price. The fallback may be cached and is therefore not treated as an
    executable quote.
    """
    symbol = f"{b.upper()}USDT"
    browser_headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/154.0 Safari/537.36",
        "Accept": "application/json,text/plain,*/*",
        "Accept-Language": "en-US,en;q=0.9",
        "Referer": "https://www.bitunix.com/",
        "Origin": "https://www.bitunix.com",
    }
    last_err = None

    # 1) Bitunix's documented direct Spot endpoint.
    try:
        url = f"https://api.bitunix.com/api/spot/v1/market/last_price?symbol={symbol}"
        d = _http_json(url, timeout=8.0, extra_headers=browser_headers)
        if str(d.get("code")) not in {"0", "200"}:
            raise RuntimeError(str(d.get("msg") or "Bitunix spot error")[:80])
        px = float(d["data"])
        if px > 0:
            return px, None, 0.0
    except Exception as e:
        last_err = e

    # 2) CoinGecko exchange-specific ticker fallback.
    #    Prefer the configured API key when available, but do not require one.
    try:
        cg_id = COINGECKO_ID_MAP.get(b.upper(), b.lower()) if "COINGECKO_ID_MAP" in globals() else b.lower()
        cg_url = (
            f"https://api.coingecko.com/api/v3/coins/{cg_id}/tickers"
            f"?exchange_ids=bitunix&include_exchange_logo=false&page=1"
        )
        cg_headers = {
            "User-Agent": "Nobody-Dealer-Suite/1.0",
            "Accept": "application/json",
        }
        try:
            cg_key = str(st.secrets.get("coingecko_api_key", "") or os.environ.get("COINGECKO_API_KEY", "")).strip()
        except Exception:
            cg_key = str(os.environ.get("COINGECKO_API_KEY", "")).strip()
        if cg_key:
            cg_headers["x-cg-demo-api-key"] = cg_key
        d = _http_json(cg_url, timeout=8.0, extra_headers=cg_headers)
        tickers = d.get("tickers") or []
        candidates = []
        for x in tickers:
            base = str(x.get("base") or "").upper()
            target = str(x.get("target") or "").upper()
            market = x.get("market") or {}
            if base != b.upper() or target not in {"USDT", "USDC", "USD"}:
                continue
            try:
                last = float(x.get("last") or 0.0)
                usd_px = float((x.get("converted_last") or {}).get("usd") or 0.0)
                volume_usd = float((x.get("converted_volume") or {}).get("usd") or 0.0)
                px = usd_px if usd_px > 0 else last
            except (TypeError, ValueError):
                continue
            if px > 0:
                candidates.append((px, volume_usd, str(market.get("name") or "Bitunix")))
        if candidates:
            # Highest reported USD turnover is the preferred Bitunix ticker.
            px, vol, _market_name = max(candidates, key=lambda z: z[1])
            return px, None, vol, "CoinGecko"
    except Exception as e:
        last_err = e

    raise RuntimeError(
        f"Bitunix Spot unavailable: {type(last_err).__name__ if last_err else 'unknown'}"
    )


def _spot_deribit(b: str) -> tuple[float, float, float]:
    # Deribit Spot supports BTC_USDC and BTC_USDT. Use BTC_USDC as the primary
    # USD-denominated spot reference; its API ticker returns last + 24h stats.
    instrument = f"{b.upper()}_USDC"
    d = _http_json(f"https://www.deribit.com/api/v2/public/ticker?instrument_name={instrument}")["result"]
    last = float(d["last_price"])
    stats = d.get("stats") or {}
    chg = float(stats.get("price_change") or 0.0)
    turn = float(stats.get("volume_usd") or 0.0)
    return last, chg, turn


def _spot_aster_global(b: str) -> tuple[float, float, float]:
    d = _http_json(f"https://sapi.asterdex.com/api/v3/ticker/24hr?symbol={b.upper()}USDT")
    return float(d["lastPrice"]), float(d.get("priceChangePercent") or 0.0), float(d.get("quoteVolume") or 0.0)


