def _cg_pick (
rows :list [dict ],v :dict ,base :str 
)->Optional [tuple [float ,float ,float ]]:
    """เลือกคู่ของกระดานนั้น; ถ้ามีหลายคู่ เลือกที่ volume สูงสุด"""
    ok_ids ={base +"USDT",base +"USDTSWAP"}
    if v ["name"]=="Hyperliquid":
        ok_ids |={base ,base +"USDC"}
    if v ["name"]=="Deribit":
        ok_ids |={base +"PERPETUAL"}

    best =None 
    for r in rows :
        exchange_name =re .sub (
        r"[^a-z0-9]","",str (r .get ("exchange_name","")).lower ()
        )
        if not exchange_name .startswith (v ["cg"]):
            continue 

        iid =re .sub (r"[^A-Z0-9]","",str (r .get ("instrument_id","")).upper ())
        if iid not in ok_ids :
            continue 

        try :
            px =float (r ["current_price"])
            chg =float (r ["price_change_percent_24h"])
            vol =float (r .get ("volume_usd")or 0 )
        except (KeyError ,TypeError ,ValueError ):
            continue 

        if px >0 and (best is None or vol >best [2 ]):
            best =(px ,chg ,vol )

    return best 


@_cache_data (ttl =30 ,show_spinner =False )
def fetch_perp_venues (base :str ="BTC")->tuple [pd.DataFrame ,str ]:
    """Fetch the Global Spot Venue Board.

    Kept under the historical function name so existing callers do not break.
    Every venue on this board is now SPOT; no perpetual ticker is used here.
    """
    venues = [(v, "spot") for v in _GLOBAL_SPOT_VENUES]

    def one(item: tuple[dict, str]) -> dict:
        v, market_type = item
        row = dict(
            exchange=v["name"],
            symbol=v["sym"](base),
            url=v["url"](base),
            price=None,
            chg=None,
            turnover=None,
            err=None,
            via=None,
            market_type=market_type,
        )
        try:
            result = v["fn"](base)
            if isinstance(result, tuple) and len(result) == 4:
                p, c, t, via = result
                row["via"] = via
            else:
                p, c, t = result
            if not (p > 0):
                raise ValueError("bad price")
            row.update(price=p, chg=c, turnover=t)
        except urllib.error.HTTPError as e:
            row["err"] = f"HTTP {e.code}"
        except Exception as e:
            row["err"] = type(e).__name__
        return row

    with ThreadPoolExecutor(max_workers=len(venues)) as ex:
        rows = list(ex.map(one, venues))

    df = pd.DataFrame(rows)
    df["_type_order"] = 0
    df = df.sort_values(["_type_order", "turnover"], ascending=[True, False], na_position="last")
    df = df.drop(columns="_type_order")
    return df.reset_index(drop=True), pd.Timestamp.now("Asia/Bangkok").strftime("%H:%M:%S")


# ==========================================================================
# PERP ARBITRAGE INSIGHT LAYER
# ใช้ราคาที่ดึงได้จริงจากแต่ละ venue เพื่อชี้ cross-venue price dislocation
# หมายเหตุ: price ในตารางเป็น observed/last price ไม่ใช่ executable bid/ask
# ==========================================================================
ARB_HIGHLIGHT_THRESHOLD_PCT = 0.02
ARB_ALERT_THRESHOLD_PCT = 0.05
# Fallback สำหรับกระดานที่ไม่มี preset: 0.10% เป็นสมมติฐานระดับ Spot ทั่วไป
# (เดิม 0.05% เป็นระดับ perp จึงทำให้ net edge ของ Spot ดูดีเกินจริง)
# ควรตรวจ fee tier จริงของบัญชีแล้วเพิ่ม preset ใน config.yaml
DEFAULT_TAKER_FEE_PCT = 0.10

_VENUE_TO_FEE_PRESET = {
    "Binance": "Binance",
    "OKX": "OKX",
    "Coinbase": "Coinbase",
    "Kraken": "Kraken",
    "Bitget": None,
    "Gate": None,
    "Bitunix": None,
    "Deribit": None,
    "Aster": None,
}


def _valid_perp_rows(rows: list[dict]) -> list[dict]:
    """Historical helper name; now returns all usable Global Spot rows."""
    out = []
    for r in rows:
        try:
            price = float(r.get("price"))
        except (TypeError, ValueError):
            continue
        if price > 0 and not r.get("err"):
            out.append(r)
    return out


def compute_arb_highlights(rows: list[dict]) -> dict:
    """หา venue ราคาต่ำสุด/สูงสุดจากข้อมูลที่สำเร็จจริง

    ใช้ threshold เพื่อไม่ให้ spread เล็กมากกลายเป็น signal หลอก
    """
    valid = _valid_perp_rows(rows)
    if len(valid) < 2:
        return {}
    cheapest = min(valid, key=lambda r: float(r["price"]))
    priciest = max(valid, key=lambda r: float(r["price"]))
    lo = float(cheapest["price"])
    hi = float(priciest["price"])
    spread_pct = ((hi - lo) / lo * 100.0) if lo > 0 else 0.0
    if spread_pct < ARB_HIGHLIGHT_THRESHOLD_PCT:
        return {}
    return {
        "buy_venue": cheapest["exchange"],
        "buy_price": lo,
        "sell_venue": priciest["exchange"],
        "sell_price": hi,
        "spread_pct": spread_pct,
        "spread_abs": hi - lo,
    }


def compute_spread_badge(rows: list[dict]) -> Optional[dict]:
    valid = _valid_perp_rows(rows)
    if len(valid) < 2:
        return None
    prices = [float(r["price"]) for r in valid]
    lo, hi = min(prices), max(prices)
    spread_pct = ((hi - lo) / lo * 100.0) if lo > 0 else 0.0
    return {
        "spread_pct": spread_pct,
        "spread_abs": hi - lo,
        "is_alert": spread_pct >= ARB_ALERT_THRESHOLD_PCT,
        "low_venue": min(valid, key=lambda r: float(r["price"]))["exchange"],
        "high_venue": max(valid, key=lambda r: float(r["price"]))["exchange"],
    }


def _valid_global_market_rows(rows: list[dict]) -> list[dict]:
    """All venue rows with usable observed prices, regardless of market type."""
    out = []
    for r in rows:
        try:
            price = float(r.get("price"))
        except (TypeError, ValueError):
            continue
        if price > 0 and not r.get("err"):
            out.append(r)
    return out


def compute_cross_market_highlights(rows: list[dict]) -> dict:
    """Compare observed prices across the Global Spot venues for the same asset.

    This is a cross-market price monitor, not an executable arbitrage quote: the
    board currently uses ticker/last prices rather than synchronized bid/ask.
    """
    valid = _valid_global_market_rows(rows)
    if len(valid) < 2:
        return {}
    buy = min(valid, key=lambda r: float(r["price"]))
    sell = max(valid, key=lambda r: float(r["price"]))
    buy_px = float(buy["price"])
    sell_px = float(sell["price"])
    if buy_px <= 0 or buy is sell:
        return {}
    spread_pct = (sell_px / buy_px - 1.0) * 100.0
    if spread_pct < ARB_HIGHLIGHT_THRESHOLD_PCT:
        return {}
    return {
        "buy_venue": str(buy["exchange"]),
        "buy_price": buy_px,
        "buy_market": str(buy.get("market_type") or "perp").lower(),
        "sell_venue": str(sell["exchange"]),
        "sell_price": sell_px,
        "sell_market": str(sell.get("market_type") or "perp").lower(),
        "spread_pct": spread_pct,
        "spread_abs": sell_px - buy_px,
    }


