def _toggle_fav (sym :str )->None :
    favs =list (st .session_state .get ("favorite_tickers",[]))
    if sym in favs :
        favs .remove (sym )
    else :
        favs .append (sym )
    st .session_state ["favorite_tickers"]=favs 
    try :
        save_favorites (favs )
    except OSError :
        pass 

