    def _alert_level(value, watch, high, *, inverse=False):
        """Return system status tone for a threshold-only risk check."""
        if inverse:
            if value < high:
                return "red", "HIGH"
            if value < watch:
                return "warn", "WATCH"
            return "ok", "OK"
        if value >= high:
            return "red", "HIGH"
        if value >= watch:
            return "warn", "WATCH"
        return "ok", "OK"

