def ask_ai (messages ,api_key ,system_override :Optional [str ]=None ):
    # Primary model + fallbacks. 503/5xx can be transient capacity errors;
    # do not expose those directly to the user when another Gemini endpoint works.
    # Current GA models. Gemini 2.5 Flash-Lite is intentionally removed:
    # new users may receive HTTP 404 because access is restricted.
    AI_MODELS = [
        "gemini-3.5-flash-lite",
        "gemini-3.1-flash-lite",
        "gemini-3.5-flash",
        "gemini-3-flash-preview",
    ]

    formatted_messages =[]
    for msg in messages :
        role ="model"if msg ["role"]=="assistant"else "user"
        formatted_messages .append ({"role":role ,"parts":[{"text":msg ["content"]}]})

    payload ={
    "systemInstruction":{"parts":[{"text":system_override or AI_SYSTEM }]},
    "contents":formatted_messages ,
    "generationConfig":{
    "maxOutputTokens":1500 ,
    "thinkingConfig":{"thinkingLevel":"low"}
    }
    }

    last_detail =""
    last_code =None

    for model_index ,AI_MODEL in enumerate (AI_MODELS ):
        url =f"https://generativelanguage.googleapis.com/v1beta/models/{AI_MODEL }:generateContent?key={api_key }"
        req =urllib .request .Request (
        url ,
        data =json .dumps (payload ).encode ("utf-8"),
        headers ={"Content-Type":"application/json"}
        )

        for attempt in range (2 ):
            try :
                with urllib .request .urlopen (req ,timeout =45 )as response :
                    result =json .loads (response .read ().decode ("utf-8"))
                    return result ["candidates"][0 ] ["content"]["parts"][0 ]["text"]

            except urllib .error.HTTPError as e :
                last_code =e .code
                try :
                    raw =e .read ().decode ("utf-8")
                    detail =json .loads (raw ).get ("error",{}).get ("message","")
                except Exception :
                    detail =""
                last_detail =detail

                # Capacity/rate-limit errors are retryable.  After a short
                # retry, move to the next model so the UI stays usable.
                # 404 can mean the selected model is unavailable to this
                # API project/user. Treat it as a model-level failure and
                # continue to the next supported model.
                if e .code in (404 ,429 ,500 ,502 ,503 ,504 ):
                    if e .code == 404 :
                        break
                    if attempt ==0 :
                        import time as _time
                        _time .sleep (0.8 )
                        continue
                    break

                return f"เรียก AI ไม่สำเร็จ (HTTP {e .code }) {detail }"

            except Exception as e :
                last_detail =str (e )
                if attempt ==0 :
                    import time as _time
                    _time .sleep (0.4 )
                    continue
                break

    if last_code in (429 ,500 ,502 ,503 ,504 ):
        return "ตอนนี้บริการ Gemini ไม่พร้อมชั่วคราว ระบบลองโมเดลสำรองแล้ว แต่ยังไม่ได้คำตอบจาก AI"
    return f"ข้อผิดพลาดระบบ: {last_detail }"

