def _ai_bubble (role :str ,text :str )->str :
    t =_html .escape (str (text ))
    t =re .sub (r"\*\*(.+?)\*\*",r"<b>\1</b>",t )
    t =t .replace ("\n","<br>")
    cls ="user"if role =="user"else "bot"
    return f'<div class="ai-row {cls }"><div class="ai-bub">{t }</div></div>'

