EVENT_BUS_TABLE = "rules_event_bus"
_EVENT_BUS_LOCAL = _HERE / "event_bus.json"
_EVENT_BUS_MAX = 500

_EVENT_TYPE_LABELS = {
    "portfolio_state": "Portfolio State",
    "risk_state": "Risk State",
    "market_state": "Market State",
    "rule_triggered": "Rule Triggered",
}


def _event_bus_actor() -> str:
    """Return the authenticated actor key used by the existing app persistence layer."""
    try:
        actor = str(_current_actor() or "").strip().lower()
    except Exception:
        actor = ""
    if is_guest_mode() or not actor or actor == "unknown":
        return ""
    return actor


def _event_bus_load_local(limit: int = _EVENT_BUS_MAX) -> list[dict[str, Any]]:
    try:
        if _EVENT_BUS_LOCAL.exists():
            raw = json.loads(_EVENT_BUS_LOCAL.read_text(encoding="utf-8"))
            rows = raw if isinstance(raw, list) else []
            return rows[-limit:]
    except Exception:
        pass
    return []


def _event_bus_save_local(events: list[dict[str, Any]]) -> None:
    try:
        _EVENT_BUS_LOCAL.write_text(
            json.dumps(events[-_EVENT_BUS_MAX:], ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
    except Exception:
        pass


def _event_fingerprint(event_type: str, payload: dict[str, Any]) -> str:
    raw = json.dumps(
        {"type": event_type, "payload": payload},
        ensure_ascii=False,
        sort_keys=True,
        default=str,
    )
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:20]


def _event_bus_load_persistent(limit: int = 500) -> tuple[list[dict[str, Any]], str]:
    """Load Event Bus from Supabase, with local fallback."""
    actor = _event_bus_actor()
    if actor:
        sb = _get_supabase()
        if sb is not None:
            try:
                res = (
                    sb.table(EVENT_BUS_TABLE)
                    .select("id,actor,event_type,source,timestamp,payload,fingerprint")
                    .eq("actor", actor)
                    .order("timestamp", desc=True)
                    .limit(int(limit))
                    .execute()
                )
                rows = list(reversed(res.data or []))
                return rows, "supabase"
            except Exception as exc:
                st.session_state["event_bus_persistence_error"] = str(exc)

    return _event_bus_load_local(limit), "local"


def emit_event(
    event_type: str,
    payload: dict[str, Any],
    *,
    source: str = "rules_engine",
    dedupe_seconds: int = 300,
) -> dict[str, Any] | None:
    """Publish an observational event to Supabase when available, else local JSON.

    This layer never places orders and never mutates portfolio state.
    """
    now = datetime.now(timezone.utc)
    actor = _event_bus_actor()
    event = {
        "id": uuid.uuid4().hex[:16],
        "actor": actor,
        "event_type": str(event_type),
        "source": str(source),
        "timestamp": now.isoformat(),
        "payload": _json_safe(payload),
        "fingerprint": _event_fingerprint(event_type, payload),
    }

    # Read the recent persistent stream first so duplicate reruns do not create noise.
    recent, _ = _event_bus_load_persistent(limit=100)
    cutoff = now.timestamp() - max(0, int(dedupe_seconds))
    for old in reversed(recent):
        try:
            old_ts = datetime.fromisoformat(str(old.get("timestamp", "")).replace("Z", "+00:00")).timestamp()
        except Exception:
            continue
        if old_ts < cutoff:
            break
        if (
            old.get("fingerprint") == event["fingerprint"]
            and old.get("event_type") == event_type
            and old.get("source") == source
        ):
            return None

    if actor:
        sb = _get_supabase()
        if sb is not None:
            try:
                sb.table(EVENT_BUS_TABLE).insert(event).execute()
                st.session_state["event_bus_persistence_mode"] = "supabase"
                return event
            except Exception as exc:
                st.session_state["event_bus_persistence_error"] = str(exc)

    # Guests and unavailable Supabase use the existing durable local fallback.
    local = _event_bus_load_local()
    local.append(event)
    _event_bus_save_local(local)
    st.session_state["event_bus_persistence_mode"] = "local"
    return event

def _event_bus_snapshot(context: dict[str, Any]) -> list[dict[str, Any]]:
    """Create observational state events from the current Rules context."""
    events: list[dict[str, Any]] = []
    portfolio_payload = {
        k: context.get(k)
        for k in (
            "portfolio_value_thb", "cash_pct", "fees_thb",
            "realized_pnl_thb", "unrealized_pnl_thb", "asset_count",
        )
    }
    market_payload = {
        k: context.get(k)
        for k in (
            "btc_price_thb", "eth_price_thb", "sol_price_thb",
        )
    }
    allocation_payload = {
        k: context.get(k)
        for k in ("btc_weight_pct", "eth_weight_pct", "sol_weight_pct")
    }

    for event_type, payload in (
        ("portfolio_state", portfolio_payload),
        ("market_state", market_payload),
        ("risk_state", allocation_payload),
    ):
        payload = {k: v for k, v in payload.items() if v is not None}
        if payload:
            ev = emit_event(event_type, payload, source="rules_engine", dedupe_seconds=300)
            if ev:
                events.append(ev)
    return events


def _event_bus_render(events: list[dict[str, Any]], source: str = "local") -> None:
    with st.expander("🛰️ Event Bus — Recent Events", expanded=False):
        if source == "supabase":
            st.caption("☁️ Persistent Event Bus: Supabase")
        else:
            st.caption("💾 Event Bus: local fallback")
            err = st.session_state.get("event_bus_persistence_error")
            if err:
                st.warning("Supabase Event Bus ยังไม่พร้อม — ใช้ local fallback ชั่วคราว")
        if not events:
            st.info("ยังไม่มี Event ใหม่ในรอบนี้")
        else:
            rows = []
            for ev in events[-30:][::-1]:
                rows.append({
                    "เวลา": str(ev.get("timestamp", ""))[:19].replace("T", " "),
                    "Event": _EVENT_TYPE_LABELS.get(str(ev.get("event_type")), str(ev.get("event_type"))),
                    "Source": ev.get("source", ""),
                    "Actor": ev.get("actor", ""),
                    "Fingerprint": ev.get("fingerprint", ""),
                })
            st.dataframe(pd.DataFrame(rows), use_container_width=True, hide_index=True)

        if st.button("🧹 Clear local Event Bus", key="rules_clear_event_bus"):
            try:
                _EVENT_BUS_LOCAL.write_text("[]", encoding="utf-8")
            except Exception:
                pass
            st.rerun()

def render_rules_engine (cfg :dict [str ,Any ],data :pd .DataFrame ,
market_df :Optional [pd .DataFrame ]=None )->None :
    st .markdown ("## ⚙️ Rules Engine")
    st .caption ("สร้างกฎหลายเงื่อนไขจาก Portfolio/Market Context + Event Bus — เป็น research & alert layer เท่านั้น ไม่ส่งคำสั่งซื้อขายอัตโนมัติ")

    rules =_rules_load ()
    sim =st .session_state .get ("sim",{})or {}
    context =_rules_context (sim ,market_df )
    _event_bus_snapshot(context)
    results =evaluate_rules (rules ,context )
    triggered =[r for r in results if r ["triggered"]]
    for r in triggered:
        emit_event("rule_triggered", {"rule_id": r.get("id"), "rule_name": r.get("name"), "action": r.get("action")}, source="rules_engine", dedupe_seconds=300)

    a ,b ,c =st .columns (3 )
    a .metric ("Rules",len (rules ))
    b .metric ("Enabled",sum (1 for r in rules if r .get ("enabled",True )))
    c .metric ("Triggered",len (triggered ))

    if triggered :
        st .warning ("พบ Rule ที่เข้าเงื่อนไข — ระบบจะแจ้งเตือนเท่านั้น และไม่ execute order")
        for r in triggered :
            st .error (f"⚠️ {r ['message']or r ['name']}")
    else :
        st .success ("ไม่มี Rule ใดเข้าเงื่อนไขในขณะนี้")

    event_rows, event_source = _event_bus_load_persistent(limit=500)
    _event_bus_render(event_rows, event_source)

    with st .expander ("📊 Current Rule Context",expanded =False ):
        st .dataframe (
        pd .DataFrame ([{"Field":_RULE_FIELD_LABELS .get(k,k),"Value":v }for k ,v in context .items ()]),
        use_container_width =True ,hide_index =True ,
        )

    st .markdown ("### ➕ สร้าง Rule")
    with st .form ("rules_engine_create_form",clear_on_submit =True ):
        name =st .text_input ("Rule Name",placeholder ="เช่น BTC concentration + low cash")
        logic =st .selectbox ("Condition Logic",["ALL","ANY"])
        f1 ,o1 ,v1 =st .columns ([1.5 ,0.8 ,1 ])
        with f1 :
            field1 =st .selectbox ("Condition 1",list (_RULE_FIELD_LABELS ),format_func =lambda x:_RULE_FIELD_LABELS [x])
        with o1 :
            op1 =st .selectbox ("Operator 1",list (_RULE_OPS ),format_func =lambda x:_RULE_OPS [x])
        with v1 :
            val1 =st .number_input ("Value 1",value =0.0,key ="rules_v1")
        use_second =st .checkbox ("เพิ่ม Condition ที่ 2",value =False )
        field2 =op2 =None
        val2 =0.0
        if use_second :
            f2 ,o2 ,v2 =st .columns ([1.5 ,0.8 ,1 ])
            with f2 :
                field2 =st .selectbox ("Condition 2",list (_RULE_FIELD_LABELS ),index =1,format_func =lambda x:_RULE_FIELD_LABELS [x],key ="rules_f2")
            with o2 :
                op2 =st .selectbox ("Operator 2",list (_RULE_OPS ),key ="rules_o2",format_func =lambda x:_RULE_OPS [x])
            with v2 :
                val2 =st .number_input ("Value 2",value =0.0,key ="rules_v2")
        action =st .selectbox ("Action",["log","alert"],format_func =lambda x:"บันทึก Log"if x =="log"else "แจ้งเตือน")
        message =st .text_input ("Message",placeholder ="ข้อความเมื่อ Rule trigger")
        if st .form_submit_button ("💾 Save Rule"):
            if not name .strip ():
                st .error ("กรุณาตั้งชื่อ Rule")
            else :
                conditions =[{"field":field1 ,"op":op1 ,"value":float (val1 )}]
                if use_second and field2 and op2 :
                    conditions .append ({"field":field2 ,"op":op2 ,"value":float (val2 )})
                rules .append ({
                "id":uuid .uuid4 ().hex ,"name":name .strip (),"enabled":True ,
                "logic":logic ,"conditions":conditions ,"action":action ,
                "message":message .strip (),
                "created_at":datetime .now (timezone .utc ).isoformat (),
                })
                _rules_save (rules )
                st .success ("บันทึก Rule แล้ว")
                st .rerun ()

    if rules :
        st .markdown ("### 📜 Rule Registry")
        registry =[]
        for r in rules :
            registry .append ({
            "Enabled":"🟢"if r .get ("enabled",True )else "⚪",
            "Rule":r .get ("name",""),"Logic":r .get ("logic","ALL"),
            "Conditions":len (r .get ("conditions",[])),"Action":r .get ("action","log"),
            "ID":r .get ("id","")[:8],
            })
        st .dataframe (pd .DataFrame (registry ),use_container_width =True ,hide_index =True )

        selected_id =st .selectbox (
        "เลือก Rule",
        [str (r .get ("id",""))for r in rules ],
        format_func =lambda rid:next ((r .get ("name","")for r in rules if str (r .get ("id",""))==rid),rid),
        key ="rules_manage_select",
        )
        m1 ,m2 =st .columns (2 )
        with m1 :
            if st .button ("⏸️ Disable / Enable",key ="rules_toggle"):
                for r in rules :
                    if str (r .get ("id",""))==selected_id :
                        r ["enabled"]=not bool (r .get ("enabled",True ))
                _rules_save (rules )
                st .rerun ()
        with m2 :
            if st .button ("🗑️ Delete Rule",key ="rules_delete"):
                rules =[r for r in rules if str (r .get ("id",""))!=selected_id]
                _rules_save (rules )
                st .rerun ()

        st .markdown ("### 🔍 Evaluation Details")
        eval_rows =[]
        for r in results :
            for ch in r ["checks"]:
                eval_rows .append ({
                "Rule":r ["name"],"Field":_RULE_FIELD_LABELS .get (ch ["field"],ch ["field"]),
                "Actual":ch ["actual"],"Operator":ch ["op"],"Target":ch ["target"],
                "Pass":"YES"if ch ["passed"]else "NO","Triggered":"YES"if r ["triggered"]else "NO",
                })
        if eval_rows :
            st .dataframe (pd .DataFrame (eval_rows ),use_container_width =True ,hide_index =True )
    else :
        st .info ("ยังไม่มี Rule — สร้าง Rule แรกด้านบนได้เลย")

    st .info ("Rule definition → reusable evaluator → read-only context. ต่อ Event Bus / Experiment Registry / module integrations ได้ภายหลัง โดยไม่ผูกกับ execute_order()")


# =========================================================================
# MARKET REGIME SWITCHBOARD v1 — OPERATING ENVIRONMENT LAYER
# =========================================================================
_REGIME_ASSETS = ["BTC", "ETH", "SOL", "BNB", "XRP"]

@_cache_data(ttl=900, show_spinner=False)
def _regime_fetch_close_matrix(assets: tuple[str, ...] = tuple(_REGIME_ASSETS)) -> pd.DataFrame:
    """Fetch a small cached daily close matrix used only for regime context."""
    try:
        raw = yf.download(
            [f"{a}-USD" for a in assets], period="120d", interval="1d",
            auto_adjust=False, progress=False, group_by="column", threads=True,
        )
        if raw is None or raw.empty:
            return pd.DataFrame()
        if isinstance(raw.columns, pd.MultiIndex):
            if "Close" not in raw.columns.get_level_values(0):
                return pd.DataFrame()
            close = raw["Close"].copy()
        else:
            close = raw[["Close"]].copy()
            close.columns = [assets[0]]
        close.columns = [str(c).replace("-USD", "").upper() for c in close.columns]
        return close.dropna(how="all").ffill()
    except Exception:
        return pd.DataFrame()


def _regime_num(v: Any, default: float = 0.0) -> float:
    try:
        x = float(v)
        return x if math.isfinite(x) else default
    except (TypeError, ValueError):
        return default


def _regime_bar(value: float, width: int = 10) -> str:
    n = max(0, min(width, int(round(_regime_num(value) / 100.0 * width))))
    return "█" * n + "░" * (width - n)


def _regime_switchboard_metrics(cfg: dict[str, Any], data: pd.DataFrame, market_df: Optional[pd.DataFrame]) -> dict[str, Any]:
    """Build a descriptive market-state snapshot. No price prediction and no orders."""
    symbol = str(cfg.get("asset", "BTC")).upper()
    close = pd.Series(dtype=float)
    if isinstance(data, pd.DataFrame) and not data.empty:
        for col in ("Close", "close", "Global_USD"):
            if col in data.columns:
                close = pd.to_numeric(data[col], errors="coerce").dropna()
                if not close.empty:
                    break

    ret20 = vol20 = trend_score = 0.0
    trend_direction = "NEUTRAL"
    if len(close) >= 25:
        ret20 = (float(close.iloc[-1]) / float(close.iloc[-21]) - 1.0) * 100.0 if close.iloc[-21] else 0.0
        daily_ret = close.pct_change().dropna()
        vol20 = float(daily_ret.tail(20).std(ddof=1) * math.sqrt(365) * 100.0) if len(daily_ret) >= 10 else 0.0
        ema20 = float(close.ewm(span=20, adjust=False).mean().iloc[-1])
        ema50 = float(close.ewm(span=min(50, max(20, len(close))), adjust=False).mean().iloc[-1])
        spread = ((ema20 / ema50) - 1.0) * 100.0 if ema50 else 0.0
        trend_score = min(100.0, abs(ret20) * 5.0 + abs(spread) * 15.0)
        if abs(ret20) >= 8.0 and abs(spread) >= 1.0:
            trend_direction = "UPTREND" if ret20 > 0 else "DOWNTREND"
        elif abs(ret20) >= 4.0 or abs(spread) >= 0.7:
            trend_direction = "UPTREND" if (ret20 + spread) > 0 else "DOWNTREND"

    liquidity_score, asset_volume, median_volume = 50.0, 0.0, 0.0
    if isinstance(market_df, pd.DataFrame) and not market_df.empty and "volume" in market_df.columns:
        vols = pd.to_numeric(market_df["volume"], errors="coerce").dropna()
        if not vols.empty:
            median_volume = float(vols.median())
            row = market_df[market_df["symbol"].astype(str).str.upper() == symbol] if "symbol" in market_df.columns else pd.DataFrame()
            if not row.empty:
                asset_volume = _regime_num(row.iloc[0].get("volume"), 0.0)
            if median_volume > 0 and asset_volume > 0:
                ratio = asset_volume / median_volume
                liquidity_score = max(0.0, min(100.0, 50.0 + 35.0 * math.log2(max(ratio, 0.125))))

    closes = _regime_fetch_close_matrix()
    avg_corr = 0.0
    if isinstance(closes, pd.DataFrame) and closes.shape[1] >= 2:
        try:
            corr = closes.pct_change().tail(60).corr()
            vals = corr.where(~np.eye(len(corr), dtype=bool)).stack().abs()
            avg_corr = float(vals.mean()) if not vals.empty else 0.0
        except Exception:
            pass
    corr_score = max(0.0, min(100.0, avg_corr * 100.0))

    vol_state = "HIGH VOLATILITY" if vol20 >= 90.0 else ("ELEVATED VOLATILITY" if vol20 >= 45.0 else "LOW / NORMAL VOLATILITY")
    liq_state = "LOW LIQUIDITY" if liquidity_score < 35 else ("NORMAL LIQUIDITY" if liquidity_score < 65 else "HIGH LIQUIDITY")
    trend_state = "TRENDING" if trend_score >= 45 and trend_direction != "NEUTRAL" else "RANGE / MIXED"
    regime = f"{vol_state} / {liq_state} / {trend_direction if trend_state == 'TRENDING' else 'RANGE'}"

    extreme, thin, trending = vol20 >= 90.0, liquidity_score < 35.0, trend_state == "TRENDING"
    compatibility = {
        "Trend-following profile": "ACTIVE" if trending and not thin else ("DEGRADED" if trending or not thin else "UNSUITABLE"),
        "Mean-reversion profile": "ACTIVE" if (not trending and not extreme and not thin) else ("DEGRADED" if not extreme else "UNSUITABLE"),
        "DCA / accumulation profile": "ACTIVE" if not extreme and not thin else ("DEGRADED" if not thin else "UNSUITABLE"),
    }
    return {"symbol": symbol, "ret20": ret20, "vol20": vol20, "trend_score": trend_score,
            "trend_direction": trend_direction, "liquidity_score": liquidity_score, "asset_volume": asset_volume,
            "median_volume": median_volume, "avg_corr": avg_corr, "corr_score": corr_score,
            "vol_state": vol_state, "liq_state": liq_state, "trend_state": trend_state,
            "regime": regime, "compatibility": compatibility}


@st.cache_data(ttl=900, show_spinner=False)
def _regime_macro_snapshot() -> dict[str, Any]:
    out={"dxy":None,"vix":None,"us10y":None,"spx":None,"qqq":None,"gold":None,"macro_state":"DATA UNAVAILABLE","risk_state":"UNKNOWN"}
    if yf is None: return out
    tickers={"dxy":"DX-Y.NYB","vix":"^VIX","us10y":"^TNX","spx":"^GSPC","qqq":"QQQ","gold":"GC=F"}
    try:
        raw=yf.download(list(tickers.values()),period="3mo",interval="1d",auto_adjust=False,progress=False,threads=False)
        if raw is None or raw.empty: return out
        close=raw["Close"] if isinstance(raw.columns,pd.MultiIndex) and "Close" in raw.columns.get_level_values(0) else raw
        inv={v:k for k,v in tickers.items()}; vals={}
        for ticker,series in close.items():
            ss=pd.to_numeric(series,errors="coerce").dropna()
            if len(ss): vals[inv.get(ticker,ticker)]=(float(ss.iloc[-1]),float((ss.iloc[-1]/ss.iloc[-22]-1)*100) if len(ss)>=22 and ss.iloc[-22] else 0.0)
        for k,pair in vals.items(): out[k]=pair[0]
        vix=float(out["vix"] or 0); dxy=vals.get("dxy",(0,0))[1]; spx=vals.get("spx",(0,0))[1]; qqq=vals.get("qqq",(0,0))[1]
        if vix>=30 and dxy>1 and (spx<0 or qqq<0): out["macro_state"]="RISK-OFF / TIGHT"
        elif vix>=22 or dxy>2 or (spx<-5 and qqq<-5): out["macro_state"]="CAUTIOUS / MIXED"
        elif vix<18 and dxy<=1 and spx>0: out["macro_state"]="RISK-ON / SUPPORTIVE"
        else: out["macro_state"]="MIXED / TRANSITION"
        out["risk_state"]="RISK-OFF" if "RISK-OFF" in out["macro_state"] else ("RISK-ON" if "RISK-ON" in out["macro_state"] else "MIXED")
    except Exception as exc: out["error"]=str(exc)
    return out

def _regime_micro_snapshot(symbol: str="BTCUSDT") -> dict[str,Any]:
    """Read public Binance Spot depth with multiple host fallbacks.

    Streamlit Cloud/hosted regions can reach one Binance public host but not
    another. Keep the calculation identical; only the transport endpoint
    changes. This prevents a venue connectivity issue from appearing as
    genuine "DATA UNAVAILABLE" market structure.
    """
    out={"symbol":symbol,"spread_bps":None,"imbalance":None,"depth_score":None,
         "micro_state":"DATA UNAVAILABLE","buy_pressure":None,"source":None}
    urls=[
        f"https://data-api.binance.vision/api/v3/depth?symbol={symbol}&limit=20",
        f"https://api.binance.com/api/v3/depth?symbol={symbol}&limit=20",
        f"https://api1.binance.com/api/v3/depth?symbol={symbol}&limit=20",
        f"https://api2.binance.com/api/v3/depth?symbol={symbol}&limit=20",
        f"https://api3.binance.com/api/v3/depth?symbol={symbol}&limit=20",
        f"https://api4.binance.com/api/v3/depth?symbol={symbol}&limit=20",
        f"https://api-gcp.binance.com/api/v3/depth?symbol={symbol}&limit=20",
    ]
    last_err=None
    for url in urls:
        try:
            book=_http_json(url,timeout=5.0) or {}
            bids=book.get("bids") or []; asks=book.get("asks") or []
            if not bids or not asks:
                raise RuntimeError("empty order book")
            bp,ap=float(bids[0][0]),float(asks[0][0]); mid=(bp+ap)/2
            out["spread_bps"]=((ap-bp)/mid*10000) if mid else None
            bq=sum(float(x[1]) for x in bids); aq=sum(float(x[1]) for x in asks)
            total=bq+aq; out["imbalance"]=((bq-aq)/total) if total else 0.0
            out["buy_pressure"]=(out["imbalance"]+1)*50
            out["depth_score"]=max(0,min(100,50+out["imbalance"]*50))
            out["source"]="Binance Spot order book"
            if out["spread_bps"]>12 and out["imbalance"]<-.20: out["micro_state"]="THIN / SELL PRESSURE"
            elif out["spread_bps"]>12: out["micro_state"]="THIN LIQUIDITY"
            elif out["imbalance"]>.20: out["micro_state"]="BUY-SIDE PRESSURE"
            elif out["imbalance"]<-.20: out["micro_state"]="SELL-SIDE PRESSURE"
            else: out["micro_state"]="BALANCED / NORMAL"
            return out
        except Exception as exc:
            last_err=exc
    out["error"]=str(last_err) if last_err else "order book unavailable"
    return out



@st.cache_data(ttl=60, show_spinner=False)
def _regime_derivatives_snapshot(symbol: str = "BTCUSDT") -> dict[str, Any]:
    """Descriptive derivatives snapshot.

    Funding/OI/taker-flow come from Binance USDⓈ-M public market-data REST.
    Liquidation history uses CoinGlass only when COINGLASS_API_KEY is configured;
    Binance's historical market-wide liquidation REST endpoint is no longer
    maintained, so the UI must not pretend that a missing feed is zero.
    No execution or account data is touched.
    """
    base = symbol.upper().replace("USDT", "")
    out = {
        "symbol": symbol,
        "funding_rate": None,
        "funding_state": "DATA UNAVAILABLE",
        "open_interest": None,
        "open_interest_usd": None,
        "oi_change_1h_pct": None,
        "oi_state": "DATA UNAVAILABLE",
        "taker_buy": None,
        "taker_sell": None,
        "taker_imbalance": None,
        "taker_source": None,
        "flow_state": "DATA UNAVAILABLE",
        "liq_long_usd": None,
        "liq_short_usd": None,
        "liq_total_usd": None,
        "liq_state": "DATA UNAVAILABLE",
        "liquidation_source": None,
        "source": "Binance USDⓈ-M public market data",
        "errors": [],
    }

    # Binance USDⓈ-M endpoints. Keep a web-host fallback for hosted regions
    # where fapi.binance.com can be unreachable.
    fapi_hosts = ["https://fapi.binance.com", "https://www.binance.com"]

    # Funding rate: latest funding history, with premium-index fallback.
    funding = None
    for host in fapi_hosts:
        try:
            rows = _http_json(f"{host}/fapi/v1/fundingRate?symbol={symbol}&limit=1", timeout=6.0)
            if isinstance(rows, list) and rows:
                funding = float(rows[-1].get("fundingRate"))
                break
        except Exception as exc:
            out["errors"].append(f"funding:{type(exc).__name__}")
    if funding is None:
        for host in fapi_hosts:
            try:
                prem = _http_json(f"{host}/fapi/v1/premiumIndex?symbol={symbol}", timeout=6.0)
                if isinstance(prem, dict) and prem.get("lastFundingRate") not in (None, ""):
                    funding = float(prem.get("lastFundingRate"))
                    break
            except Exception as exc:
                out["errors"].append(f"premium:{type(exc).__name__}")
    if funding is not None:
        out["funding_rate"] = funding
        if funding >= 0.0003:
            out["funding_state"] = "HIGH POSITIVE"
        elif funding <= -0.0003:
            out["funding_state"] = "HIGH NEGATIVE"
        else:
            out["funding_state"] = "NORMAL"

    # Current OI + 1h historical comparison.
    oi_qty = None
    mark_price = None
    for host in fapi_hosts:
        try:
            d = _http_json(f"{host}/fapi/v1/openInterest?symbol={symbol}", timeout=6.0)
            oi_qty = float(d.get("openInterest"))
            break
        except Exception as exc:
            out["errors"].append(f"oi:{type(exc).__name__}")
    for host in fapi_hosts:
        try:
            d = _http_json(f"{host}/fapi/v1/premiumIndex?symbol={symbol}", timeout=6.0)
            if isinstance(d, dict):
                mark_price = float(d.get("markPrice"))
                break
        except Exception as exc:
            out["errors"].append(f"mark:{type(exc).__name__}")
    if oi_qty is not None:
        out["open_interest"] = oi_qty
        if mark_price and mark_price > 0:
            out["open_interest_usd"] = oi_qty * mark_price

    for host in fapi_hosts:
        try:
            hist = _http_json(
                f"{host}/futures/data/openInterestHist?symbol={symbol}&period=1h&limit=2",
                timeout=7.0,
            )
            if isinstance(hist, list) and len(hist) >= 2:
                prev = float(hist[-2].get("sumOpenInterestValue") or 0.0)
                curr = float(hist[-1].get("sumOpenInterestValue") or 0.0)
                if prev > 0:
                    out["oi_change_1h_pct"] = (curr / prev - 1.0) * 100.0
                break
        except Exception as exc:
            out["errors"].append(f"oi_hist:{type(exc).__name__}")
    if out["open_interest"] is not None:
        chg = out.get("oi_change_1h_pct")
        if chg is None:
            out["oi_state"] = "CURRENT ONLY"
        elif chg >= 3:
            out["oi_state"] = "RISING FAST"
        elif chg <= -3:
            out["oi_state"] = "FALLING FAST"
        elif chg > 0.5:
            out["oi_state"] = "RISING"
        elif chg < -0.5:
            out["oi_state"] = "FALLING"
        else:
            out["oi_state"] = "STABLE"

    # Taker buy/sell flow.
    # Primary: Binance aggregate taker endpoint.
    # Fallback: public aggTrades.  The aggTrades `m` flag tells whether the
    # buyer was the maker: m=False => buyer was taker (aggressive buy),
    # m=True => seller was taker (aggressive sell). This avoids returning
    # DATA UNAVAILABLE just because the /futures/data endpoint is blocked.
    taker_ok = False
    for host in fapi_hosts:
        try:
            rows = _http_json(
                f"{host}/futures/data/takerBuySellVol?symbol={symbol}&contractType=PERPETUAL&period=5m&limit=1",
                timeout=7.0,
            )
            if isinstance(rows, list) and rows:
                row = rows[-1]
                buy = float(row.get("buyVolValue") or row.get("buyVol") or 0.0)
                sell = float(row.get("sellVolValue") or row.get("sellVol") or 0.0)
                total = buy + sell
                if total > 0:
                    out["taker_buy"], out["taker_sell"] = buy, sell
                    out["taker_imbalance"] = (buy - sell) / total
                    out["taker_source"] = "Binance takerBuySellVol · 5m"
                    taker_ok = True
                break
        except Exception as exc:
            out["errors"].append(f"taker:{type(exc).__name__}")

    # Fallback: reconstruct the latest taker pressure from recent aggregate trades.
    if not taker_ok:
        for host in fapi_hosts:
            try:
                trades = _http_json(
                    f"{host}/fapi/v1/aggTrades?symbol={symbol}&limit=1000",
                    timeout=8.0,
                )
                if isinstance(trades, list) and trades:
                    now_ms = int(time.time() * 1000)
                    cutoff_ms = now_ms - 5 * 60 * 1000
                    buy_v = sell_v = 0.0
                    for tr in trades:
                        ts = int(tr.get("T") or 0)
                        if ts and ts < cutoff_ms:
                            continue
                        px = float(tr.get("p") or 0.0)
                        qty = float(tr.get("q") or 0.0)
                        value = px * qty
                        if value <= 0:
                            continue
                        if bool(tr.get("m")):
                            sell_v += value
                        else:
                            buy_v += value
                    total = buy_v + sell_v
                    if total > 0:
                        out["taker_buy"], out["taker_sell"] = buy_v, sell_v
                        out["taker_imbalance"] = (buy_v - sell_v) / total
                        out["taker_source"] = "Binance aggTrades fallback · latest 5m"
                        taker_ok = True
                    break
            except Exception as exc:
                out["errors"].append(f"taker_agg:{type(exc).__name__}")

    ti = out.get("taker_imbalance")
    if ti is not None:
        if ti >= 0.20:
            out["flow_state"] = "BUY PRESSURE"
        elif ti <= -0.20:
            out["flow_state"] = "SELL PRESSURE"
        else:
            out["flow_state"] = "BALANCED"

    # Liquidations: first try the public Binance market-wide liquidation stream.
    # Binance documents this as !forceOrder@arr; it is a WebSocket stream, not
    # a historical REST endpoint. We sample it briefly and cache the result.
    # CoinGlass remains the historical 1h fallback when an API key is configured.
    liq_stream_ok = False
    try:
        import websocket as _ws  # optional dependency: websocket-client
        ws = _ws.create_connection(
            "wss://fstream.binance.com/market/ws/!forceOrder@arr",
            timeout=2.5,
            enable_multithread=True,
        )
        ws.settimeout(0.8)
        deadline = time.time() + 2.0
        events = []
        while time.time() < deadline:
            try:
                raw = ws.recv()
            except Exception:
                break
            if not raw:
                continue
            try:
                payload = json.loads(raw)
            except Exception:
                continue
            data = payload.get("data", payload) if isinstance(payload, dict) else {}
            order = data.get("o", {}) if isinstance(data, dict) else {}
            if str(order.get("s", "")).upper() != symbol.upper():
                continue
            qty = float(order.get("q") or 0.0)
            avg_px = float(order.get("ap") or order.get("p") or 0.0)
            value = qty * avg_px
            if value > 0:
                events.append((str(order.get("S", "")).upper(), value))
        try:
            ws.close()
        except Exception:
            pass
        if events:
            long_v = sum(v for side, v in events if side == "SELL")
            short_v = sum(v for side, v in events if side == "BUY")
            total = long_v + short_v
            out["liq_long_usd"], out["liq_short_usd"], out["liq_total_usd"] = long_v, short_v, total
            out["liquidation_source"] = "Binance !forceOrder@arr · live sample"
            out["liq_state"] = "RECENT ACTIVITY"
            liq_stream_ok = True
        else:
            out["liquidation_source"] = "Binance !forceOrder@arr · no BTCUSDT event in sample"
            out["liq_state"] = "NO RECENT EVENT"
            liq_stream_ok = True
    except Exception as exc:
        out["errors"].append(f"liquidation_stream:{type(exc).__name__}")

    # Historical fallback: CoinGlass v4 when the user has configured an API key.
    cg_key = _coinglass_key()
    if cg_key and not liq_stream_ok:
        try:
            url = (
                "https://open-api-v4.coinglass.com/api/futures/liquidation/history"
                f"?exchange=Binance&symbol={symbol}&interval=1h&limit=6"
            )
            doc = _http_json(url, timeout=8.0, extra_headers={"CG-API-KEY": cg_key})
            if str(doc.get("code")) == "0":
                rows = doc.get("data") or []
                if rows:
                    row = rows[-1]
                    long_v = float(row.get("long_liquidation_usd") or 0.0)
                    short_v = float(row.get("short_liquidation_usd") or 0.0)
                    total = long_v + short_v
                    out["liq_long_usd"], out["liq_short_usd"], out["liq_total_usd"] = long_v, short_v, total
                    out["liquidation_source"] = "CoinGlass · Binance · 1h"
                    prev = []
                    for r in rows[:-1]:
                        try:
                            prev.append(float(r.get("long_liquidation_usd") or 0.0) + float(r.get("short_liquidation_usd") or 0.0))
                        except Exception:
                            pass
                    baseline = float(np.median(prev)) if prev else 0.0
                    if baseline > 0 and total >= baseline * 2.0:
                        out["liq_state"] = "ELEVATED"
                    elif total > 0:
                        out["liq_state"] = "NORMAL"
                    else:
                        out["liq_state"] = "NONE REPORTED"
            else:
                out["errors"].append(f"liquidation:CoinGlass {doc.get('msg')}")
        except Exception as exc:
            out["errors"].append(f"liquidation:{type(exc).__name__}")
    elif not liq_stream_ok:
        out["liquidation_source"] = "Binance liquidation stream unavailable · CoinGlass API key not configured"

    return out


def _regime_environment_composite(m: dict[str, Any], macro: dict[str, Any], micro: dict[str, Any], deriv: dict[str, Any]) -> dict[str, Any]:
    """Combine Macro + Market Regime + Micro + Derivatives into one descriptive state."""
    macro_state = str(macro.get("risk_state") or "UNKNOWN")
    micro_state = str(micro.get("micro_state") or "DATA UNAVAILABLE")
    trend_state = str(m.get("trend_state") or "RANGE / MIXED")
    vol_state = str(m.get("vol_state") or "LOW / NORMAL VOLATILITY")
    liq_state = str(m.get("liq_state") or "NORMAL LIQUIDITY")
    funding_state = str(deriv.get("funding_state") or "DATA UNAVAILABLE")
    oi_state = str(deriv.get("oi_state") or "DATA UNAVAILABLE")
    flow_state = str(deriv.get("flow_state") or "DATA UNAVAILABLE")
    liq_deriv_state = str(deriv.get("liq_state") or "DATA UNAVAILABLE")
    stress = 0; support = 0; reasons=[]; evidence=[]
    if macro_state == "RISK-OFF": stress += 2; reasons.append("Macro risk-off"); evidence.append("Macro")
    elif macro_state == "RISK-ON": support += 2; reasons.append("Macro risk-on"); evidence.append("Macro")
    elif macro_state == "MIXED": reasons.append("Macro mixed")
    if "HIGH VOLATILITY" in vol_state: stress += 2; reasons.append("High volatility"); evidence.append("Volatility")
    elif "ELEVATED VOLATILITY" in vol_state: stress += 1; reasons.append("Elevated volatility"); evidence.append("Volatility")
    if "LOW LIQUIDITY" in liq_state: stress += 2; reasons.append("Low volume liquidity proxy"); evidence.append("Liquidity")
    elif "HIGH LIQUIDITY" in liq_state: support += 1
    if "SELL" in micro_state: stress += 2; reasons.append("Sell-side microstructure"); evidence.append("Micro")
    elif "THIN" in micro_state: stress += 2; reasons.append("Thin micro liquidity"); evidence.append("Micro")
    elif "BUY" in micro_state: support += 2; reasons.append("Buy-side microstructure"); evidence.append("Micro")
    if funding_state == "HIGH POSITIVE": stress += 1; reasons.append("High positive funding"); evidence.append("Funding")
    elif funding_state == "HIGH NEGATIVE": stress += 1; reasons.append("High negative funding"); evidence.append("Funding")
    if oi_state == "RISING FAST": reasons.append("Open interest rising fast"); evidence.append("OI")
    elif oi_state == "FALLING FAST": reasons.append("Open interest falling fast"); evidence.append("OI")
    if "SELL" in flow_state: stress += 2; reasons.append("Taker sell pressure"); evidence.append("Taker Flow")
    elif "BUY" in flow_state: support += 2; reasons.append("Taker buy pressure"); evidence.append("Taker Flow")
    if liq_deriv_state == "ELEVATED": stress += 2; reasons.append("Elevated liquidations"); evidence.append("Liquidations")
    if stress >= 6: state="STRESSED"
    elif stress >= 3: state="FRAGILE"
    elif support >= 4 and stress == 0: state="SUPPORTIVE"
    else: state="BALANCED / MIXED"
    trend_label = str(m.get("trend_direction")) if trend_state == "TRENDING" and m.get("trend_direction") not in (None,"NEUTRAL") else "RANGE / MIXED"
    return {"state":state,"score":stress-support,"stress":stress,"support":support,"trend":trend_label,"macro":macro_state,"micro":micro_state,"funding":funding_state,"oi":oi_state,"flow":flow_state,"liquidations":liq_deriv_state,"reasons":reasons[:8],"evidence":list(dict.fromkeys(evidence))}


def _regime_transition_update(snapshot: dict[str, Any]) -> dict[str, Any]:
    """Keep a small in-session state history and detect state transitions."""
    history=st.session_state.setdefault("_regime_transition_history",[])
    fp=json.dumps(snapshot,sort_keys=True,ensure_ascii=False,default=str)
    now=datetime.now(timezone.utc).isoformat()
    if not history or history[-1].get("fingerprint") != fp:
        history.append({"timestamp":now,"fingerprint":fp,**snapshot})
        st.session_state["_regime_transition_history"]=history[-48:]
    current=st.session_state["_regime_transition_history"][-1]
    previous=st.session_state["_regime_transition_history"][-2] if len(st.session_state["_regime_transition_history"])>=2 else None
    changed=[]
    if previous:
        for key in ("environment","macro","micro","trend","funding","oi","flow","liquidations"):
            if previous.get(key)!=current.get(key): changed.append(key)
    return {"current":current,"previous":previous,"changed":changed}


def _regime_divergence_radar(m: dict[str, Any], macro: dict[str, Any], micro: dict[str, Any], deriv: dict[str, Any]) -> list[dict[str, str]]:
    """Find descriptive disagreements between trend, microstructure and derivatives."""
    findings=[]; direction=str(m.get("trend_direction") or "NEUTRAL"); micro_state=str(micro.get("micro_state") or "DATA UNAVAILABLE"); flow_state=str(deriv.get("flow_state") or "DATA UNAVAILABLE"); oi_state=str(deriv.get("oi_state") or "DATA UNAVAILABLE"); funding_state=str(deriv.get("funding_state") or "DATA UNAVAILABLE")
    if direction=="UPTREND" and ("SELL" in micro_state or "SELL" in flow_state): findings.append({"Signal":"Price vs Flow","Status":"DIVERGENCE","Detail":"Trend is up while short-term sell pressure is present."})
    if direction=="DOWNTREND" and ("BUY" in micro_state or "BUY" in flow_state): findings.append({"Signal":"Price vs Flow","Status":"DIVERGENCE","Detail":"Trend is down while short-term buy pressure is present."})
    if direction=="UPTREND" and oi_state in ("RISING","RISING FAST") and funding_state=="HIGH POSITIVE": findings.append({"Signal":"Trend + Leverage","Status":"WATCH","Detail":"Uptrend, rising open interest and high positive funding are aligned."})
    if direction=="DOWNTREND" and oi_state in ("RISING","RISING FAST") and funding_state=="HIGH NEGATIVE": findings.append({"Signal":"Trend + Leverage","Status":"WATCH","Detail":"Downtrend, rising open interest and high negative funding are aligned."})
    if "THIN" in micro_state and str(m.get("vol_state","")).startswith("HIGH"): findings.append({"Signal":"Liquidity vs Volatility","Status":"STRESS","Detail":"Thin micro liquidity is coinciding with high volatility."})
    if macro.get("risk_state")=="RISK-OFF" and direction=="UPTREND": findings.append({"Signal":"Macro vs Trend","Status":"DIVERGENCE","Detail":"Macro is risk-off while the observed price trend remains upward."})
    if macro.get("risk_state")=="RISK-ON" and direction=="DOWNTREND": findings.append({"Signal":"Macro vs Trend","Status":"DIVERGENCE","Detail":"Macro is risk-on while the observed price trend remains downward."})
    return findings


def _shadow_portfolio_init() -> dict[str, Any]:
    state = st.session_state.setdefault("_shadow_portfolio_v1", {})
    if not isinstance(state, dict):
        state = {}
        st.session_state["_shadow_portfolio_v1"] = state
    state.setdefault("initial_cash", 1_000_000.0)
    state.setdefault("cash", 1_000_000.0)
    state.setdefault("qty", 0.0)
    state.setdefault("avg_cost", 0.0)
    state.setdefault("realized_pnl", 0.0)
    state.setdefault("fees", 0.0)
    state.setdefault("trades", [])
    state.setdefault("equity_history", [])
    state.setdefault("last_run", None)
    state.setdefault("strategy", "Regime Adaptive")
    return state


def _shadow_signal(strategy: str, m: dict[str, Any], envx: dict[str, Any], micro: dict[str, Any], deriv: dict[str, Any]) -> tuple[str, str]:
    trend = str(m.get("trend_direction") or "NEUTRAL")
    regime = str(m.get("regime") or "")
    env = str(envx.get("state") or "BALANCED")
    micro_state = str(micro.get("micro_state") or "")
    flow = str(deriv.get("flow_state") or "")
    vol = str(m.get("vol_state") or "")
    oi = str(deriv.get("oi_state") or "")

    if strategy == "Trend Following":
        if trend == "UPTREND" and ("SELL" not in micro_state) and ("SELL" not in flow) and env not in ("STRESSED",):
            return "BUY", "Uptrend with no confirmed short-term sell pressure"
        if trend == "DOWNTREND" and ("BUY" not in micro_state) and ("BUY" not in flow):
            return "SELL", "Downtrend with no confirmed short-term buy pressure"
        return "HOLD", f"Trend state={trend}; no execution condition"

    if strategy == "Mean Reversion":
        if ("RANGE" in regime or "MIXED" in regime or env == "BALANCED") and "HIGH" not in vol:
            if "SELL" in micro_state or "SELL" in flow:
                return "BUY", "Range/mixed environment with short-term sell pressure"
            if "BUY" in micro_state or "BUY" in flow:
                return "SELL", "Range/mixed environment with short-term buy pressure"
        return "HOLD", f"Regime={regime}; volatility={vol}"

    if strategy == "DCA":
        if env != "STRESSED" and "THIN" not in micro_state:
            return "BUY", "Periodic accumulation allowed while environment is not stressed"
        return "HOLD", f"Accumulation paused: environment={env}, micro={micro_state}"

    # Regime Adaptive
    if env == "SUPPORTIVE" and trend == "UPTREND" and ("SELL" not in flow):
        return "BUY", "Supportive environment + uptrend + flow not sell-side"
    if env in ("FRAGILE", "STRESSED") and (trend == "DOWNTREND" or "SELL" in flow or "SELL" in micro_state):
        return "SELL", "Stress environment with downside/sell-side confirmation"
    if env == "BALANCED" and trend == "UPTREND" and ("BUY" in micro_state or "BUY" in flow):
        return "BUY", "Balanced environment with aligned upside signals"
    return "HOLD", f"Environment={env}; trend={trend}; micro={micro_state}; flow={flow}; OI={oi}"


def _shadow_execute(state: dict[str, Any], signal: str, reason: str, price: float, envx: dict[str, Any], m: dict[str, Any], asset: str) -> dict[str, Any]:
    fee_rate = 0.0025
    slippage_rate = 0.0005
    equity_before = state["cash"] + state["qty"] * price
    max_trade = max(1_000.0, equity_before * 0.10)
    signal = signal.upper()
    executed = False
    qty_delta = 0.0
    fill = price
    if signal == "BUY" and state["cash"] >= 1_000.0:
        gross = min(max_trade, state["cash"])
        fill = price * (1.0 + slippage_rate)
        fee = gross * fee_rate
        spend = min(state["cash"], gross)
        qty = max(0.0, (spend - fee) / fill)
        if qty > 0:
            old_qty = state["qty"]
            old_cost = old_qty * state["avg_cost"]
            state["qty"] = old_qty + qty
            state["avg_cost"] = (old_cost + spend) / state["qty"] if state["qty"] > 0 else 0.0
            state["cash"] -= spend
            state["fees"] += fee
            qty_delta = qty
            executed = True
    elif signal == "SELL" and state["qty"] > 0:
        qty = min(state["qty"], max_trade / max(price, 1e-9))
        fill = price * (1.0 - slippage_rate)
        gross = qty * fill
        fee = gross * fee_rate
        realized = gross - fee - qty * state["avg_cost"]
        state["qty"] -= qty
        state["cash"] += gross - fee
        state["realized_pnl"] += realized
        state["fees"] += fee
        qty_delta = -qty
        executed = True
    trade = {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "asset": asset,
        "signal": signal,
        "executed": executed,
        "price": float(price),
        "fill": float(fill),
        "qty": float(qty_delta),
        "reason": reason,
        "environment": envx.get("state", "—"),
        "regime": m.get("regime", "—"),
        "fee_rate": fee_rate,
        "slippage_rate": slippage_rate,
    }
    state["trades"].append(trade)
    state["trades"] = state["trades"][-200:]
    state["last_run"] = trade["timestamp"]
    equity_after = state["cash"] + state["qty"] * price
    state["equity_history"].append({"timestamp": trade["timestamp"], "equity": equity_after, "price": price})
    state["equity_history"] = state["equity_history"][-500:]
    return trade


def render_shadow_portfolio(cfg: dict[str, Any], data: pd.DataFrame, market_df: Optional[pd.DataFrame] = None) -> None:
    """Paper-only autonomous strategy sandbox. Never calls execute_order or sends exchange orders."""
    state = _shadow_portfolio_init()
    asset = str(cfg.get("asset") or "BTC").upper()
    if asset == "BTC":
        asset = "BTC"
    try:
        row = data.iloc[-1]
        price = float(row.get("Global_USD", 0.0)) * float(row.get("USDTHB", 0.0))
    except Exception:
        price = 0.0
    if price <= 0:
        st.error("Shadow Portfolio: ไม่พบราคาปัจจุบันที่ใช้จำลองได้")
        return

    m = _regime_switchboard_metrics(cfg, data, market_df)
    macro = _regime_macro_snapshot()
    symbol = f"{asset}USDT"
    micro = _regime_micro_snapshot(symbol)
    deriv = _regime_derivatives_snapshot(symbol)
    envx = _regime_environment_composite(m, macro, micro, deriv)

    st.markdown("## 🤖 Shadow Portfolio")
    st.caption("Autonomous Trading Lab · paper-only · จำลอง execution เท่านั้น · ไม่ส่งคำสั่งซื้อขายจริง")
    c1, c2, c3 = st.columns(3)
    strategy = c1.selectbox("Strategy", ["Regime Adaptive", "Trend Following", "Mean Reversion", "DCA"], index=["Regime Adaptive", "Trend Following", "Mean Reversion", "DCA"].index(state.get("strategy", "Regime Adaptive")), key="shadow_strategy")
    state["strategy"] = strategy
    capital = c2.number_input("Initial Capital (THB)", min_value=10_000.0, value=float(state.get("initial_cash", 1_000_000.0)), step=10_000.0, key="shadow_capital")
    if capital != state.get("initial_cash") and not state.get("trades"):
        state["initial_cash"] = float(capital); state["cash"] = float(capital)

    signal, reason = _shadow_signal(strategy, m, envx, micro, deriv)
    equity = state["cash"] + state["qty"] * price
    total_return = (equity / state["initial_cash"] - 1.0) * 100.0 if state["initial_cash"] else 0.0
    a,b,c,d,e = st.columns(5)
    a.metric("Shadow Equity", f"฿{equity:,.0f}", f"{total_return:+.2f}%")
    b.metric(f"{asset} Position", f"{state['qty']:.8f}")
    c.metric("Cash", f"฿{state['cash']:,.0f}")
    d.metric("Realized P&L", f"฿{state['realized_pnl']:,.0f}")
    e.metric("Fees", f"฿{state['fees']:,.0f}")

    st.markdown("### 🧠 Current Autonomous Decision")
    dc1, dc2, dc3 = st.columns(3)
    dc1.metric("Signal", signal)
    dc2.metric("Environment", envx["state"])
    dc3.metric("Market Regime", m["regime"])
    st.info(f"**Why:** {reason}\n\nCurrent simulated price: ฿{price:,.2f} · Trade size cap: 10% of equity · Fee: 0.25% · Slippage assumption: 0.05%")

    r1, r2 = st.columns(2)
    with r1:
        if st.button("▶️ Run Shadow Cycle", type="primary", use_container_width=True, key="shadow_run_cycle"):
            trade = _shadow_execute(state, signal, reason, price, envx, m, asset)
            emit_event("SHADOW_DECISION", {"strategy": strategy, "asset": asset, "signal": signal, "executed": trade["executed"], "reason": reason, "price": price, "environment": envx["state"], "regime": m["regime"]}, source="shadow_portfolio", dedupe_seconds=30)
            st.success(f"Shadow cycle: {signal} · {'EXECUTED' if trade['executed'] else 'HOLD / NO FILL'}")
            st.rerun()
    with r2:
        if st.button("♻️ Reset Shadow Portfolio", use_container_width=True, key="shadow_reset"):
            st.session_state.pop("_shadow_portfolio_v1", None)
            st.rerun()

    st.markdown("### 🛡️ Shadow Risk Gate")
    gate_rows = [
        {"Gate": "Real exchange execution", "Status": "BLOCKED", "Reason": "Shadow module never calls execute_order"},
        {"Gate": "Max trade size", "Status": "PASS", "Reason": "10% of current equity"},
        {"Gate": "Fee + slippage", "Status": "PASS", "Reason": "0.25% fee + 0.05% slippage simulated"},
        {"Gate": "Audit event", "Status": "PASS", "Reason": "Decision written to Event Bus"},
    ]
    st.dataframe(pd.DataFrame(gate_rows), use_container_width=True, hide_index=True)

    with st.expander("📜 Shadow Trade History", expanded=False):
        if state["trades"]:
            rows = [{"Time": str(t["timestamp"])[:19].replace("T", " "), "Signal": t["signal"], "Executed": "YES" if t["executed"] else "NO", "Qty": f"{t['qty']:+.8f}", "Price": f"฿{t['price']:,.2f}", "Environment": t["environment"], "Reason": t["reason"]} for t in reversed(state["trades"][-50:])]
            st.dataframe(pd.DataFrame(rows), use_container_width=True, hide_index=True)
        else:
            st.caption("ยังไม่มี Shadow Cycle")

    with st.expander("📊 Shadow Performance", expanded=False):
        hist = state.get("equity_history", [])
        if hist:
            eq = [float(x["equity"]) for x in hist]
            peak = max([state["initial_cash"]] + eq)
            max_dd = min([(x / max(state["initial_cash"], 1e-9) - 1.0) * 100.0 for x in eq] or [0.0])
            st.write({"Cycles": len(hist), "Return": f"{total_return:+.2f}%", "Peak Equity": f"฿{peak:,.0f}", "Worst observed return": f"{max_dd:+.2f}%"})
        else:
            st.caption("ยังไม่มี performance history")

def render_market_regime_switchboard(cfg: dict[str, Any], data: pd.DataFrame, market_df: Optional[pd.DataFrame] = None) -> None:
    m=_regime_switchboard_metrics(cfg,data,market_df); macro=_regime_macro_snapshot(); asset=f"{str(cfg.get('asset','BTC')).upper()}USDT"; micro=_regime_micro_snapshot(asset); deriv=_regime_derivatives_snapshot(asset); envx=_regime_environment_composite(m,macro,micro,deriv)
    st.markdown("## 🧠 Market Regime Switchboard")
    st.caption("Operating Environment Layer — Macro + Market Regime + Micro Structure + Derivatives · descriptive only · ไม่ทำนายราคา · ไม่ส่งคำสั่งซื้อขาย")
    c1,c2,c3,c4=st.columns(4); c1.metric("Trend",f"{m['trend_score']:.0f}/100",m["trend_direction"]); c2.metric("Volatility",f"{m['vol20']:.1f}%",m["vol_state"]); c3.metric("Liquidity proxy",f"{m['liquidity_score']:.0f}/100",m["liq_state"]); c4.metric("Correlation",f"{m['avg_corr']*100:.0f}%","cross-asset")
    st.markdown(f'''<div style="background:linear-gradient(135deg,#171A20 0%,#101318 100%);border:1px solid #2B3139;border-radius:14px;padding:18px;margin:12px 0 18px;"><div style="font-size:11px;color:#8B93A1;letter-spacing:.08em;">CURRENT MARKET REGIME · {_html.escape(m['symbol'])}</div><div style="font-size:24px;font-weight:800;color:#EAECEF;margin-top:7px;">{_html.escape(m['regime'])}</div><div style="font-size:12px;color:#8B93A1;margin-top:8px;">20D return {m['ret20']:+.2f}% · annualized 20D volatility {m['vol20']:.1f}% · avg cross-asset correlation {m['avg_corr']*100:.1f}%</div></div>''',unsafe_allow_html=True)
    st.markdown("### 🌍 Macro Environment"); ma,mb,mc,md=st.columns(4); ma.metric("Macro Regime",macro.get("macro_state","—")); mb.metric("VIX",f"{macro['vix']:.1f}" if macro.get("vix") is not None else "—"); mc.metric("DXY",f"{macro['dxy']:.2f}" if macro.get("dxy") is not None else "—"); md.metric("US 10Y",f"{macro['us10y']:.2f}%" if macro.get("us10y") is not None else "—")
    st.markdown("### 🧬 Micro Market Structure"); xa,xb,xc,xd=st.columns(4); xa.metric("Micro State",micro.get("micro_state","—")); xb.metric("Spread",f"{micro['spread_bps']:.2f} bps" if micro.get("spread_bps") is not None else "—"); xc.metric("Book Imbalance",f"{micro['imbalance']*100:+.1f}%" if micro.get("imbalance") is not None else "—"); xd.metric("Buy Pressure",f"{micro['buy_pressure']:.0f}/100" if micro.get("buy_pressure") is not None else "—")
    macro_flag=macro.get("risk_state","UNKNOWN"); micro_flag=micro.get("micro_state","DATA UNAVAILABLE")
    if macro_flag=="RISK-OFF" and ("SELL" in micro_flag or "THIN" in micro_flag): env="FRAGILE — MACRO RISK-OFF + WEAK MICROSTRUCTURE"
    elif macro_flag=="RISK-ON" and "BUY" in micro_flag: env="SUPPORTIVE — MACRO RISK-ON + BUY-SIDE MICROSTRUCTURE"
    elif "THIN" in micro_flag: env="CAUTION — MICRO LIQUIDITY FRAGILE"
    else: env=f"{macro_flag} / {micro_flag}"
    st.info(f"**Combined Environment:** {env}\n\nMacro: {macro_flag} · Micro: {micro_flag}")
    st.markdown("### 📉 Derivatives Environment"); da,db,dc,dd=st.columns(4); da.metric("Funding",f"{deriv['funding_rate']*100:.4f}%" if deriv.get("funding_rate") is not None else "—",deriv.get("funding_state","—")); oi_label=f"${deriv['open_interest_usd']/1e9:.2f}B" if deriv.get("open_interest_usd") is not None else (f"{deriv['open_interest']:,.2f}" if deriv.get("open_interest") is not None else "—"); db.metric("Open Interest",oi_label,deriv.get("oi_state","—")); dc.metric("Taker Flow",f"{deriv['taker_imbalance']*100:+.1f}%" if deriv.get("taker_imbalance") is not None else "—",deriv.get("flow_state","—")); dd.metric("Liquidations",f"${deriv['liq_total_usd']/1e6:.1f}M" if deriv.get("liq_total_usd") is not None else "—",deriv.get("liq_state","—"))
    if deriv.get("oi_change_1h_pct") is not None: st.caption(f"OI 1h change: {deriv['oi_change_1h_pct']:+.2f}% · Taker flow = latest 5m aggregate")
    if deriv.get("liquidation_source"): st.caption(f"Liquidation source: {deriv['liquidation_source']}")
    if deriv.get("funding_rate") is None and deriv.get("open_interest") is None: st.warning("Derivatives data ยังไม่ตอบกลับจาก Binance USDⓈ-M — ไม่ตีความเป็น 0")

    st.markdown("### 🧠 Environment Composite"); ec1,ec2,ec3,ec4=st.columns(4); ec1.metric("Environment",envx["state"],f"stress {envx['stress']} · support {envx['support']}"); ec2.metric("Trend Context",envx["trend"]); ec3.metric("Macro",envx["macro"]); ec4.metric("Micro",envx["micro"])
    if envx["reasons"]: st.caption("Drivers: "+" · ".join(envx["reasons"]))
    if envx["evidence"]: st.caption("Evidence feeds: "+", ".join(envx["evidence"]))

    transition_snapshot={"environment":envx["state"],"macro":envx["macro"],"micro":envx["micro"],"trend":envx["trend"],"funding":envx["funding"],"oi":envx["oi"],"flow":envx["flow"],"liquidations":envx["liquidations"]}; transition=_regime_transition_update(transition_snapshot)
    if transition["changed"] and transition["previous"]:
        prev=transition["previous"]; st.warning(f"**⚠️ REGIME TRANSITION DETECTED** — {prev.get('environment','—')} → {envx['state']} · changed: {', '.join(transition['changed'])}")
        emit_event("REGIME_CHANGED",{"symbol":asset,"from":prev.get("environment"),"to":envx["state"],"changed":transition["changed"],**transition_snapshot},source="market_regime_switchboard",dedupe_seconds=300)

    st.markdown("### 🔎 Divergence Radar"); divergences=_regime_divergence_radar(m,macro,micro,deriv)
    if divergences: st.dataframe(pd.DataFrame(divergences),use_container_width=True,hide_index=True); st.caption("Divergence Radar flags disagreements between observed datasets; it is not a buy/sell signal.")
    else: st.success("No material cross-signal divergence detected from the currently available feeds.")

    a,b=st.columns(2)
    with a:
        st.markdown("### 🌡️ Environment Signals"); st.markdown(f"**Trend**  `{_regime_bar(m['trend_score'])}` {m['trend_score']:.0f}/100"); st.markdown(f"**Volatility**  `{_regime_bar(min(100,m['vol20']/1.5))}` {m['vol20']:.1f}%"); st.markdown(f"**Liquidity**  `{_regime_bar(m['liquidity_score'])}` {m['liquidity_score']:.0f}/100"); st.markdown(f"**Correlation**  `{_regime_bar(m['corr_score'])}` {m['avg_corr']*100:.1f}%"); st.caption("Liquidity เป็น volume proxy จาก market overview; ไม่ใช่ bid/ask spread หรือ order-book depth โดยตรง")
    with b:
        st.markdown("### 🧩 Strategy Compatibility"); st.dataframe(pd.DataFrame([{"Profile":k,"State":v} for k,v in m["compatibility"].items()]),use_container_width=True,hide_index=True); st.caption("Compatibility เป็น environment check แบบ descriptive เท่านั้น ไม่ผูกกับ execution engine")
    with st.expander("🕰️ Regime Transition History",expanded=False):
        hist=st.session_state.get("_regime_transition_history",[])
        if hist:
            rows=[{"Time UTC":str(x.get("timestamp",""))[:19].replace("T"," "),"Environment":x.get("environment","—"),"Macro":x.get("macro","—"),"Micro":x.get("micro","—"),"Trend":x.get("trend","—"),"Funding":x.get("funding","—"),"OI":x.get("oi","—"),"Flow":x.get("flow","—"),"Liquidations":x.get("liquidations","—")} for x in reversed(hist[-24:])]; st.dataframe(pd.DataFrame(rows),use_container_width=True,hide_index=True)
        else: st.caption("ยังไม่มี transition history ใน session นี้")
    with st.expander("🔬 Regime Diagnostics",expanded=False):
        diag=pd.DataFrame([{"Signal":"20D Return","Value":f"{m['ret20']:+.2f}%"},{"Signal":"Trend Direction","Value":m["trend_direction"]},{"Signal":"Annualized 20D Volatility","Value":f"{m['vol20']:.2f}%"},{"Signal":"Liquidity Volume","Value":f"{m['asset_volume']:,.0f}" if m["asset_volume"] else "—"},{"Signal":"Cross-Asset Avg Abs Correlation","Value":f"{m['avg_corr']*100:.2f}%"},{"Signal":"Environment Composite","Value":envx["state"]},{"Signal":"Funding Rate","Value":f"{deriv['funding_rate']*100:.4f}%" if deriv.get("funding_rate") is not None else "—"},{"Signal":"OI 1h Change","Value":f"{deriv['oi_change_1h_pct']:+.2f}%" if deriv.get("oi_change_1h_pct") is not None else "—"},{"Signal":"Taker Flow","Value":f"{deriv['taker_imbalance']*100:+.1f}%" if deriv.get("taker_imbalance") is not None else "—"},{"Signal":"Liquidation State","Value":deriv.get("liq_state","—")},{"Signal":"Transition Changed","Value":", ".join(transition["changed"]) if transition["changed"] else "—"}]); st.dataframe(diag,use_container_width=True,hide_index=True)


def render_quant_research_hub (cfg :dict [str ,Any ],data :pd .DataFrame ,market_df :Optional [pd .DataFrame ]=None )->None :
    """Single entry point for all Quant Research tools.

    Keeps the desktop navigation compact while preserving every existing
    Quant page and its function unchanged.
    """
    st .markdown ("## 🧪 Quant Research Lab")
    st .caption ("รวมเครื่องมือ Quant ทั้งหมดไว้ที่เดียว แล้วเลือกโมดูลที่ต้องการจากเมนูด้านล่าง")

    # แบ่ง Quant เป็นหมวดก่อน แล้วค่อยเลือกโมดูล เพื่อไม่ให้ dropdown ยาวเกินไป
    quant_groups ={
    "📚 Research & Evaluation":[
    NAV_RESEARCH_SCORECARD ,
    NAV_PRODUCTION_GATE ,
    NAV_TRANSACTION_COST_LAB ,
    NAV_PBO_DSR_LAB ,
    ],
    "🛡️ Risk & Stress":[
    NAV_STRESS_LAB ,
    NAV_HEALTH_SCORE ,
    ],
    "🧠 Market Environment":[
    NAV_REGIME_SWITCHBOARD ,
    ],
    "🕶️ Shadow & Governance":[
    NAV_SHADOW_MODE ,
    NAV_SHADOW_PORTFOLIO ,
    NAV_EXPERIMENT_TRACKER ,
    NAV_MODEL_GOVERNANCE ,
    NAV_DECISION_LOG ,
    NAV_RULES_ENGINE ,
    ],
    "🧬 Models & Simulation":[
    NAV_SYNTHETIC_LAB ,
    NAV_HMM_RESEARCH ,
    ],
    "🧾 Reports & Final Review":[
    NAV_RESEARCH_REPORT ,
    NAV_FINAL_QUANT_REVIEW ,
    ],
    }

    default_page =st .session_state .get ("quant_research_section",NAV_RESEARCH_SCORECARD )
    if default_page not in QUANT_RESEARCH_PAGES :
        default_page =NAV_RESEARCH_SCORECARD 

    default_group =next (
    (group for group ,pages in quant_groups .items ()if default_page in pages ),
    next (iter (quant_groups )),
    )

    c_group ,c_module =st .columns ([0.9 ,1.6 ],gap ="small")
    with c_group :
        selected_group =st .selectbox (
        "หมวด Quant",
        list (quant_groups .keys ()),
        index =list (quant_groups .keys ()).index (default_group ),
        key ="quant_research_group",
        )

    pages_in_group =quant_groups [selected_group ]
    # ถ้าผู้ใช้เปลี่ยนหมวด ให้เปิดหน้าแรกของหมวดนั้นโดยอัตโนมัติ
    if default_page not in pages_in_group :
        default_page =pages_in_group [0 ]
        st .session_state ["quant_research_section"]=default_page 

    with c_module :
        selected =st .selectbox (
        "เลือก Quant Module",
        pages_in_group ,
        index =pages_in_group .index (default_page ),
        key ="quant_research_section",
        )

    st .markdown (
    '<div style="height:1px;background:#2b3139;margin:8px 0 18px 0;"></div>',
    unsafe_allow_html =True ,
    )

    if selected ==NAV_RESEARCH_SCORECARD :
        render_research_scorecard (cfg ,data ,market_df )
    elif selected ==NAV_PRODUCTION_GATE :
        render_production_readiness_gate (cfg ,data ,market_df )
    elif selected ==NAV_SHADOW_MODE :
        render_shadow_mode (cfg ,data ,market_df )
    elif selected ==NAV_EXPERIMENT_TRACKER :
        render_experiment_tracker (cfg ,data ,market_df )
    elif selected ==NAV_MODEL_GOVERNANCE :
        render_model_governance (cfg ,data ,market_df )
    elif selected ==NAV_DECISION_LOG :
        render_portfolio_decision_log (cfg ,data ,market_df )
    elif selected ==NAV_RULES_ENGINE :
        render_rules_engine (cfg ,data ,market_df )
    elif selected ==NAV_REGIME_SWITCHBOARD :
        render_market_regime_switchboard (cfg ,data ,market_df )
    elif selected ==NAV_SHADOW_PORTFOLIO :
        render_shadow_portfolio (cfg ,data ,market_df )
    elif selected ==NAV_TRANSACTION_COST_LAB :
        render_transaction_cost_lab (cfg ,data ,market_df )
    elif selected ==NAV_PBO_DSR_LAB :
        render_pbo_dsr_lab (cfg ,data ,market_df )
    elif selected ==NAV_RESEARCH_REPORT :
        render_quant_research_report (cfg ,data ,market_df )
    elif selected ==NAV_STRESS_LAB :
        render_scenario_stress_lab (cfg ,data ,market_df )
    elif selected ==NAV_HEALTH_SCORE :
        render_portfolio_health_score (cfg ,data ,market_df )
    elif selected ==NAV_SYNTHETIC_LAB :
        render_synthetic_market_lab (cfg ,data ,market_df )
    elif selected ==NAV_HMM_RESEARCH :
        render_hmm_production_research (cfg ,data ,market_df )
    elif selected ==NAV_FINAL_QUANT_REVIEW :
        render_final_quant_production_review (cfg ,data ,market_df )



def _footer_go_to (nav :str ,*,portfolio_section :str |None =None ,
quant_section :str |None =None )->None :
    """Route Footer clicks through the app's existing navigation state."""
    # Keep the same top-level navigation state used by the desktop menu.
    st .session_state ["main_nav"]=nav 
    st .session_state ["main_nav_tabs"]=nav 
    st .session_state .pop ("main_nav_tabs_news",None )

    # Optional inner-page targets.
    if portfolio_section is not None :
        st .session_state ["portfolio_footer_target"]=portfolio_section 
    else :
        st .session_state .pop ("portfolio_footer_target",None )

    if quant_section is not None :
        st .session_state ["quant_research_section"]=quant_section 
    elif nav !=NAV_QUANT_RESEARCH :
        st .session_state .pop ("quant_research_section",None )

        # Streamlit automatically reruns after the callback.

